  rd_l2_how_h2: { en: "From \"mine!\" to shipped — in three steps", fil: "Mula \"mine!\" hanggang naipadala — sa tatlong hakbang", zh: "从“+1”到出货——只需三步", "zh-TW": "從「+1」到出貨——只需三步", vi: "Từ \"mine!\" đến giao hàng — chỉ ba bước", th: "จาก \"mine!\" ถึงจัดส่ง — ในสามขั้นตอน", id: "Dari \"mine!\" sampai terkirim — dalam tiga langkah" },
  rd_l2_how_sub: { en: "No more pausing your live to write orders in a notebook. The app watches the comments while you sell.", fil: "Hindi mo na kailangang i-pause ang live para magsulat sa notebook. Binabantayan ng app ang comments habang nagbebenta ka.", zh: "不用再暂停直播抄单。App 会在你卖货时盯着留言。", "zh-TW": "不用再暫停直播抄單。App 會在你賣貨時盯著留言。", vi: "Không cần dừng live để ghi đơn vào sổ. Ứng dụng theo dõi bình luận trong khi bạn bán.", th: "ไม่ต้องหยุดไลฟ์เพื่อจดออเดอร์อีกต่อไป แอปเฝ้าดูคอมเมนต์ให้ขณะคุณขาย", id: "Tak perlu menjeda live untuk mencatat pesanan. Aplikasi memantau komentar saat Anda berjualan." },
  rd_l2_step: { en: "STEP {n}", fil: "HAKBANG {n}", zh: "步骤 {n}", "zh-TW": "步驟 {n}", vi: "BƯỚC {n}", th: "ขั้นที่ {n}", id: "LANGKAH {n}" },
  rd_l2_s1_t: { en: "Connect your live", fil: "Ikonekta ang live mo", zh: "连接你的直播", "zh-TW": "連接你的直播", vi: "Kết nối live của bạn", th: "เชื่อมต่อไลฟ์ของคุณ", id: "Hubungkan live Anda" },
  rd_l2_s1_d: { en: "Link your TikTok or Facebook account once. When you go live, SellerFlowLive listens to every comment in real time.", fil: "I-link ang TikTok o Facebook account mo nang isang beses. Kapag nag-live ka, pinapakinggan ng SellerFlowLive ang bawat comment nang real time.", zh: "绑定一次 TikTok 或 Facebook 账号。开播后，SellerFlowLive 实时监听每一条留言。", "zh-TW": "綁定一次 TikTok 或 Facebook 帳號。開播後，SellerFlowLive 即時監聽每一則留言。", vi: "Liên kết tài khoản TikTok hoặc Facebook một lần. Khi bạn lên live, SellerFlowLive lắng nghe từng bình luận theo thời gian thực.", th: "เชื่อมบัญชี TikTok หรือ Facebook ครั้งเดียว เมื่อคุณไลฟ์ SellerFlowLive จะฟังทุกคอมเมนต์แบบเรียลไทม์", id: "Tautkan akun TikTok atau Facebook sekali saja. Saat Anda live, SellerFlowLive mendengarkan setiap komentar secara real time." },
  rd_l2_s2_t: { en: "Comments become orders", fil: "Nagiging orders ang comments", zh: "留言变订单", "zh-TW": "留言變訂單", vi: "Bình luận thành đơn hàng", th: "คอมเมนต์กลายเป็นออเดอร์", id: "Komentar menjadi pesanan" },
  rd_l2_s2_d: { en: "Every \"mine\" claim is captured instantly — buyer gets a number, order gets a price, nothing is missed even in a fast live.", fil: "Agad nahuhuli ang bawat \"mine\" — may number ang buyer, may presyo ang order, walang namimiss kahit mabilis ang live.", zh: "每条“+1”即时捕捉——买家有编号、订单有价格，再快的直播也不漏单。", "zh-TW": "每則「+1」即時擷取——買家有編號、訂單有價格，再快的直播也不漏單。", vi: "Mỗi lượt \"mine\" được bắt ngay lập tức — người mua có số, đơn có giá, không sót đơn nào dù live rất nhanh.", th: "ทุกคำว่า \"mine\" ถูกจับทันที — ผู้ซื้อได้หมายเลข ออเดอร์ได้ราคา ไม่พลาดแม้ไลฟ์จะเร็ว", id: "Setiap klaim \"mine\" langsung tertangkap — pembeli dapat nomor, pesanan dapat harga, tak ada yang terlewat meski live berjalan cepat." },
  rd_l2_s3_t: { en: "Print & ship", fil: "Print at ipadala", zh: "打印与出货", "zh-TW": "列印與出貨", vi: "In & giao hàng", th: "พิมพ์และจัดส่ง", id: "Cetak & kirim" },
  rd_l2_s3_d: { en: "Print thermal slips per buyer, sort bags by number, and export straight to 7-11 交貨便 for store pickup.", fil: "Mag-print ng thermal slips kada buyer, i-sort ang bags ayon sa number, at i-export diretso sa 7-11 交貨便 para sa store pickup.", zh: "按买家打印热敏小票、按编号分装，并直接汇出到 7-11 交貨便门店取货。", "zh-TW": "按買家列印熱感小票、按編號分裝，並直接匯出到 7-11 交貨便門市取貨。", vi: "In phiếu nhiệt theo từng người mua, soạn túi theo số, và xuất thẳng sang 7-11 交貨便 để nhận tại cửa hàng.", th: "พิมพ์สลิปความร้อนต่อผู้ซื้อ แยกถุงตามหมายเลข และส่งออกตรงไปยัง 7-11 交貨便 เพื่อรับที่ร้าน", id: "Cetak slip thermal per pembeli, sortir kantong berdasarkan nomor, dan ekspor langsung ke 7-11 交貨便 untuk pengambilan di toko." },
  rd_l2_in_eyebrow: { en: "Inside the app", fil: "Sa loob ng app", zh: "走进 App", "zh-TW": "走進 App", vi: "Bên trong ứng dụng", th: "ภายในแอป", id: "Di dalam aplikasi" },
  rd_l2_in_h2: { en: "Your whole live business, on one screen", fil: "Ang buong live business mo, sa isang screen", zh: "你的整个直播生意，尽在一屏", "zh-TW": "你的整個直播生意，盡在一屏", vi: "Toàn bộ việc bán live của bạn, trên một màn hình", th: "ธุรกิจไลฟ์ทั้งหมดของคุณ ในหน้าจอเดียว", id: "Seluruh bisnis live Anda, dalam satu layar" },
  rd_l2_in_sub: { en: "Watch it come together — orders, buyers, and revenue assembling into one clear picture.", fil: "Panoorin itong mabuo — orders, buyers, at revenue na nagsasama sa isang malinaw na picture.", zh: "看它逐步成形——订单、买家、营收汇成一张清晰的全景。", "zh-TW": "看它逐步成形——訂單、買家、營收匯成一張清晰的全景。", vi: "Xem mọi thứ ghép lại — đơn hàng, người mua và doanh thu thành một bức tranh rõ ràng.", th: "ดูทุกอย่างประกอบเข้าด้วยกัน — ออเดอร์ ผู้ซื้อ และรายได้รวมเป็นภาพเดียวที่ชัดเจน", id: "Lihat semuanya menyatu — pesanan, pembeli, dan pendapatan menjadi satu gambaran jelas." },
