  rd_l2_cta_h2: { en: "Your next live could run itself.", fil: "Ang susunod mong live, pwede nang tumakbo mag-isa.", zh: "你的下一场直播，可以自己跑起来。", "zh-TW": "你的下一場直播，可以自己跑起來。", vi: "Buổi live tiếp theo của bạn có thể tự vận hành.", th: "ไลฟ์ครั้งถัดไปของคุณอาจดำเนินไปได้ด้วยตัวเอง", id: "Live Anda berikutnya bisa berjalan sendiri." },
  rd_l2_cta_sub: { en: "Join thousands of live sellers who stopped scribbling orders and started selling more.", fil: "Samahan ang libu-libong live sellers na tumigil sa pagsusulat ng orders at nagsimulang magbenta nang mas marami.", zh: "加入数千位不再手抄订单、卖得更多的直播卖家。", "zh-TW": "加入數千位不再手抄訂單、賣得更多的直播賣家。", vi: "Tham gia cùng hàng nghìn người bán live đã ngừng ghi chép và bán được nhiều hơn.", th: "ร่วมกับผู้ขายไลฟ์หลายพันคนที่เลิกจดออเดอร์และขายได้มากขึ้น", id: "Bergabung dengan ribuan penjual live yang berhenti mencatat pesanan dan mulai menjual lebih banyak." },
  rd_l2_f_desc: { en: "The live-selling assistant for TikTok & Facebook sellers — auto-capture orders, print slips, and ship via 7-11, all in one app.", fil: "Ang live-selling assistant para sa TikTok at Facebook sellers — auto-capture ng orders, print ng slips, at padala via 7-11, lahat sa isang app.", zh: "为 TikTok 与 Facebook 卖家打造的直播助手——自动抓单、打印小票、7-11 寄件，一个 App 全搞定。", "zh-TW": "為 TikTok 與 Facebook 賣家打造的直播助手——自動抓單、列印小票、7-11 寄件，一個 App 全搞定。", vi: "Trợ lý bán live cho người bán TikTok & Facebook — tự động bắt đơn, in phiếu và giao qua 7-11, tất cả trong một ứng dụng.", th: "ผู้ช่วยขายไลฟ์สำหรับผู้ขาย TikTok และ Facebook — จับออเดอร์อัตโนมัติ พิมพ์สลิป และส่งผ่าน 7-11 ครบในแอปเดียว", id: "Asisten jualan live untuk penjual TikTok & Facebook — tangkap pesanan otomatis, cetak slip, dan kirim via 7-11, semua dalam satu aplikasi." },
  rd_l2_foot_getapp: { en: "Get the app", fil: "Kunin ang app", zh: "下载 App", "zh-TW": "下載 App", vi: "Tải ứng dụng", th: "ดาวน์โหลดแอป", id: "Unduh aplikasi" },
