  rd_ord_save_failed: { en: "Order kept on this device, but the cloud save failed — check your connection.", fil: "Naitala ang order sa device na ito, pero nabigo ang cloud save — suriin ang koneksyon.", zh: "订单已保留在本设备，但云端保存失败——请检查网络连接。", "zh-TW": "訂單已保留在本裝置，但雲端儲存失敗——請檢查網路連線。", vi: "Đơn hàng được giữ trên thiết bị này, nhưng lưu lên đám mây thất bại — hãy kiểm tra kết nối.", th: "คำสั่งซื้อถูกเก็บไว้ในเครื่องนี้ แต่บันทึกขึ้นคลาวด์ไม่สำเร็จ — โปรดตรวจสอบการเชื่อมต่อ", id: "Pesanan tersimpan di perangkat ini, tapi penyimpanan cloud gagal — periksa koneksi Anda." },
  rd_sess_load_failed: { en: "Couldn't load today's session — check your connection and reopen before selling (buyer numbers may repeat).", fil: "Hindi ma-load ang session ngayong araw — suriin ang koneksyon at buksan muli bago magbenta (baka maulit ang buyer numbers).", zh: "无法载入今天的场次——请检查网络并重新打开后再销售（买家编号可能重复）。", "zh-TW": "無法載入今天的場次——請檢查網路並重新開啟後再銷售（買家編號可能重複）。", vi: "Không tải được phiên hôm nay — kiểm tra kết nối và mở lại trước khi bán (số người mua có thể bị trùng).", th: "โหลดเซสชันวันนี้ไม่สำเร็จ — ตรวจสอบการเชื่อมต่อและเปิดใหม่ก่อนขาย (หมายเลขผู้ซื้ออาจซ้ำ)", id: "Tidak bisa memuat sesi hari ini — periksa koneksi dan buka ulang sebelum berjualan (nomor pembeli bisa terulang)." },
  rd_sp_title: { en: "Start a live session", fil: "Magsimula ng live session", zh: "开始直播场次", "zh-TW": "開始直播場次", vi: "Bắt đầu phiên live", th: "เริ่มเซสชันไลฟ์", id: "Mulai sesi live" },
  rd_sp_sub: { en: "Choose how long this session runs. Buyer numbers stay continuous for the whole session and reset only when you start a new one.", fil: "Piliin kung gaano katagal ang session na ito. Tuloy-tuloy ang buyer numbers sa buong session at magre-reset lang kapag nagsimula ka ng bago.", zh: "选择本场次的时长。整场买家编号连续，只有开始新场次时才会重置。", "zh-TW": "選擇本場次的時長。整場買家編號連續，只有開始新場次時才會重置。", vi: "Chọn thời lượng phiên này. Số người mua liền mạch suốt phiên và chỉ đặt lại khi bạn bắt đầu phiên mới.", th: "เลือกระยะเวลาของเซสชันนี้ หมายเลขผู้ซื้อจะต่อเนื่องตลอดเซสชันและรีเซ็ตเมื่อคุณเริ่มเซสชันใหม่เท่านั้น", id: "Pilih durasi sesi ini. Nomor pembeli berlanjut sepanjang sesi dan hanya diatur ulang saat Anda memulai sesi baru." },
  rd_sp_cancel: { en: "Cancel", fil: "Kanselahin", zh: "取消", "zh-TW": "取消", vi: "Hủy", th: "ยกเลิก", id: "Batal" },
  rd_sp_start_failed: { en: "Couldn't start the session — check your connection and tap Connect again.", fil: "Hindi masimulan ang session — suriin ang koneksyon at pindutin muli ang Connect.", zh: "无法开始场次——请检查网络后再次点击连接。", "zh-TW": "無法開始場次——請檢查網路後再次點擊連線。", vi: "Không bắt đầu được phiên — kiểm tra kết nối và nhấn Kết nối lại.", th: "เริ่มเซสชันไม่สำเร็จ — ตรวจสอบการเชื่อมต่อแล้วแตะเชื่อมต่ออีกครั้ง", id: "Tidak bisa memulai sesi — periksa koneksi dan ketuk Hubungkan lagi." },
  rd_win_save_failed: { en: "Couldn't save the session length — reverted. Check your connection and try again.", fil: "Hindi na-save ang session length — ibinalik. Suriin ang koneksyon at subukan muli.", zh: "无法保存场次天数——已还原。请检查网络后重试。", "zh-TW": "無法儲存場次天數——已還原。請檢查網路後重試。", vi: "Không lưu được độ dài phiên — đã hoàn tác. Kiểm tra kết nối và thử lại.", th: "บันทึกจำนวนวันของเซสชันไม่สำเร็จ — คืนค่าแล้ว ตรวจสอบการเชื่อมต่อแล้วลองใหม่", id: "Tidak bisa menyimpan panjang sesi — dikembalikan. Periksa koneksi dan coba lagi." },
  rd_raffle_save_failed: { en: "Couldn't save the Games switch — check your connection and try again.", fil: "Hindi na-save ang Games switch — suriin ang koneksyon at subukan muli.", zh: "无法保存 Games 开关——请检查网络后重试。", "zh-TW": "無法儲存 Games 開關——請檢查網路後重試。", vi: "Không lưu được công tắc Games — kiểm tra kết nối và thử lại.", th: "บันทึกสวิตช์ Games ไม่สำเร็จ — ตรวจสอบการเชื่อมต่อแล้วลองใหม่", id: "Tidak bisa menyimpan sakelar Games — periksa koneksi dan coba lagi." },
  rd_prd_sync_failed: { en: "Saved on this device, but cloud sync failed — it may not show on your other devices.", fil: "Na-save sa device na ito, pero nabigo ang cloud sync — baka hindi ito lumabas sa iba mong device.", zh: "已保存在本设备，但云端同步失败——可能不会显示在其他设备上。", "zh-TW": "已儲存在本裝置，但雲端同步失敗——可能不會顯示在其他裝置上。", vi: "Đã lưu trên thiết bị này, nhưng đồng bộ đám mây thất bại — có thể không hiển thị trên thiết bị khác.", th: "บันทึกในเครื่องนี้แล้ว แต่ซิงก์คลาวด์ไม่สำเร็จ — อาจไม่แสดงบนอุปกรณ์อื่นของคุณ", id: "Tersimpan di perangkat ini, tapi sinkron cloud gagal — mungkin tidak muncul di perangkat lain." },
  rd_prd_delete_failed: { en: "Delete failed — the product was restored. Check your connection and try again.", fil: "Nabigo ang pag-delete — ibinalik ang produkto. Suriin ang koneksyon at subukan muli.", zh: "删除失败——商品已恢复。请检查网络后重试。", "zh-TW": "刪除失敗——商品已恢復。請檢查網路後重試。", vi: "Xóa thất bại — sản phẩm đã được khôi phục. Kiểm tra kết nối và thử lại.", th: "ลบไม่สำเร็จ — สินค้าถูกกู้คืนแล้ว ตรวจสอบการเชื่อมต่อแล้วลองใหม่", id: "Gagal menghapus — produk dikembalikan. Periksa koneksi dan coba lagi." },
