  rd_shp_dl_failed: { en: "Entries were marked exported, but the file could not be generated: {err}. Try again from a computer browser.", fil: "Na-mark nang exported ang entries, pero hindi nabuo ang file: {err}. Subukan ulit sa computer browser.", zh: "资料已标记为已导出，但文件生成失败：{err}。请在电脑浏览器重试。", "zh-TW": "資料已標記為已匯出，但檔案產生失敗：{err}。請在電腦瀏覽器重試。", vi: "Mục đã đánh dấu đã xuất nhưng không tạo được tệp: {err}. Thử lại trên trình duyệt máy tính.", th: "รายการถูกทำเครื่องหมายส่งออกแล้ว แต่สร้างไฟล์ไม่สำเร็จ: {err} ลองใหม่บนเบราว์เซอร์คอมพิวเตอร์", id: "Entri ditandai diekspor tetapi file gagal dibuat: {err}. Coba lagi di browser komputer." },
  rd_shp_export_browser: { en: "Exporting the .xlsm needs a browser — open sellerflowlive.com on your computer or phone browser. Everything you encoded here is already synced.", fil: "Kailangan ng browser para i-export ang .xlsm — buksan ang sellerflowlive.com sa iyong computer o phone browser. Naka-sync na ang lahat ng na-encode mo rito.", zh: "导出 .xlsm 需要浏览器——请在电脑或手机浏览器打开 sellerflowlive.com。您在此填写的资料已同步。", "zh-TW": "匯出 .xlsm 需要瀏覽器——請在電腦或手機瀏覽器開啟 sellerflowlive.com。您在此填寫的資料已同步。", vi: "Xuất .xlsm cần trình duyệt — mở sellerflowlive.com trên máy tính hoặc trình duyệt điện thoại. Dữ liệu đã nhập ở đây đã được đồng bộ.", th: "การส่งออก .xlsm ต้องใช้เบราว์เซอร์ — เปิด sellerflowlive.com บนคอมพิวเตอร์หรือเบราว์เซอร์มือถือ ข้อมูลที่กรอกไว้ซิงค์แล้ว", id: "Ekspor .xlsm memerlukan browser — buka sellerflowlive.com di komputer atau browser ponsel. Data yang diisi di sini sudah tersinkron." },
  rd_shp_none_encoded: { en: "Encode buyers above to enable export.", fil: "I-encode muna ang mga buyer sa itaas para ma-enable ang export.", zh: "请先填写上方买家资料以启用导出。", "zh-TW": "請先填寫上方買家資料以啟用匯出。", vi: "Nhập thông tin người mua ở trên để bật xuất.", th: "กรอกข้อมูลผู้ซื้อด้านบนเพื่อเปิดใช้การส่งออก", id: "Isi data pembeli di atas untuk mengaktifkan ekspor." },
