  rd_set_auto_mode: { en: "Auto mode", fil: "Auto mode", zh: "自动模式", "zh-TW": "自動模式", vi: "Chế độ tự động", th: "โหมดอัตโนมัติ", id: "Mode otomatis" },
  rd_set_auto_desc: { en: "Map codes to products. Announce a code on live and the first buyers who type it exactly get an auto-order, until the product's stock runs out.", fil: "I-map ang mga code sa mga produkto. Mag-announce ng code sa live at ang mga unang mamimili na eksaktong magta-type nito ay makakakuha ng auto-order, hanggang maubos ang stock ng produkto.", zh: "将代码映射到产品。在直播中宣布一个代码，最先准确输入该代码的买家会自动下单，直到该产品库存售罄。", "zh-TW": "將代碼對應到產品。在直播中公布一個代碼，最先準確輸入該代碼的買家會自動成立訂單，直到該產品庫存售完。", vi: "Gán mã cho sản phẩm. Công bố một mã khi live và những người mua đầu tiên gõ đúng mã sẽ được tạo đơn tự động, cho đến khi sản phẩm hết hàng.", th: "จับคู่โค้ดกับสินค้า ประกาศโค้ดระหว่างไลฟ์ ผู้ซื้อกลุ่มแรกที่พิมพ์โค้ดตรงเป๊ะจะได้รับออเดอร์อัตโนมัติ จนกว่าสต็อกสินค้าจะหมด", id: "Petakan kode ke produk. Umumkan kode saat live dan pembeli pertama yang mengetiknya persis akan mendapat pesanan otomatis, sampai stok produk habis." },
  rd_set_keepawake: { en: "Keep screen awake while live", fil: "Panatilihing gising ang screen habang live", zh: "直播时保持屏幕常亮", "zh-TW": "直播時保持螢幕恆亮", vi: "Giữ màn hình sáng khi đang live", th: "ให้หน้าจอติดค้างระหว่างไลฟ์", id: "Jaga layar tetap menyala saat live" },
  rd_set_keepawake_desc: { en: "Prevents the phone from sleeping while connected — a sleeping phone stops capturing orders.", fil: "Pinipigilan ang telepono na matulog habang naka-connect — ang natutulog na telepono ay hindi nakakakuha ng orders.", zh: "连接期间防止手机休眠——手机休眠会停止接单。", "zh-TW": "連線期間防止手機休眠——手機休眠會停止接單。", vi: "Ngăn điện thoại ngủ khi đang kết nối — điện thoại ngủ sẽ ngừng ghi nhận đơn.", th: "ป้องกันไม่ให้โทรศัพท์เข้าสู่โหมดสลีประหว่างเชื่อมต่อ — โทรศัพท์ที่หลับจะหยุดรับออเดอร์", id: "Mencegah ponsel tidur saat terhubung — ponsel yang tidur berhenti menangkap pesanan." },
  rd_set_motion: { en: "Animations", fil: "Mga animation", zh: "动画效果", "zh-TW": "動畫效果", vi: "Hiệu ứng chuyển động", th: "แอนิเมชัน", id: "Animasi" },
  rd_set_motion_desc: { en: "Turn off looping motion to save battery on older phones or reduce distraction during a live.", fil: "I-off ang paulit-ulit na galaw para makatipid ng baterya sa lumang telepono o mabawasan ang distraction habang live.", zh: "关闭循环动画可在旧手机上省电，或减少直播时的干扰。", "zh-TW": "關閉循環動畫可在舊手機上省電，或減少直播時的干擾。", vi: "Tắt hiệu ứng lặp để tiết kiệm pin trên máy cũ hoặc giảm phân tâm khi đang live.", th: "ปิดแอนิเมชันแบบวนซ้ำเพื่อประหยัดแบตบนเครื่องรุ่นเก่า หรือลดสิ่งรบกวนระหว่างไลฟ์", id: "Matikan animasi berulang untuk menghemat baterai di ponsel lama atau mengurangi gangguan saat live." },
  rd_auto_codes_title: { en: "Code → product", fil: "Code → produkto", zh: "代码 → 产品", "zh-TW": "代碼 → 產品", vi: "Mã → sản phẩm", th: "โค้ด → สินค้า", id: "Kode → produk" },
  rd_auto_count: { en: "{n} / 26", fil: "{n} / 26", zh: "{n} / 26", "zh-TW": "{n} / 26", vi: "{n} / 26", th: "{n} / 26", id: "{n} / 26" },
  rd_auto_help: { en: "Announce a code on live. Buyers who type it exactly get an auto-order at this price, until stock runs out.", fil: "Mag-announce ng code sa live. Ang mga mamimili na eksaktong magta-type nito ay makakakuha ng auto-order sa presyong ito, hanggang maubos ang stock.", zh: "在直播中宣布一个代码。准确输入该代码的买家会以此价格自动下单，直到库存售罄。", "zh-TW": "在直播中公布一個代碼。準確輸入該代碼的買家會以此價格自動成立訂單，直到庫存售完。", vi: "Công bố một mã khi live. Người mua gõ đúng mã sẽ được tạo đơn tự động theo giá này, cho đến khi hết hàng.", th: "ประกาศโค้ดระหว่างไลฟ์ ผู้ซื้อที่พิมพ์โค้ดตรงเป๊ะจะได้รับออเดอร์อัตโนมัติตามราคานี้ จนกว่าสินค้าจะหมด", id: "Umumkan kode saat live. Pembeli yang mengetiknya persis akan mendapat pesanan otomatis dengan harga ini, sampai stok habis." },
