  rd_prn_title: { en: "No printer connected", fil: "Walang nakakonektang printer", zh: "未连接打印机", "zh-TW": "沒有連接印表機", vi: "Chưa kết nối máy in", th: "ยังไม่ได้เชื่อมต่อเครื่องพิมพ์", id: "Tidak ada printer terhubung" },
  rd_prn_body: { en: "Your order was saved, but it couldn't print — no printer is set up yet. Set up your printer, then reprint from Orders.", fil: "Na-save ang order, pero hindi ma-print — wala pang naka-setup na printer. I-setup ang printer, tapos i-reprint mula sa Orders.", zh: "订单已保存，但无法打印——尚未设置打印机。请设置打印机，然后从「订单」重新打印。", "zh-TW": "訂單已儲存，但無法列印——尚未設定印表機。請設定印表機，然後從「訂單」重新列印。", vi: "Đơn hàng đã được lưu, nhưng không in được — chưa thiết lập máy in. Hãy thiết lập máy in, rồi in lại từ Đơn hàng.", th: "บันทึกออร์เดอร์แล้ว แต่พิมพ์ไม่ได้ — ยังไม่ได้ตั้งค่าเครื่องพิมพ์ ตั้งค่าเครื่องพิมพ์ แล้วพิมพ์ซ้ำจากออร์เดอร์", id: "Pesanan tersimpan, tetapi tidak bisa dicetak — printer belum disiapkan. Siapkan printer, lalu cetak ulang dari Pesanan." },
  rd_prn_go: { en: "Go to Printer Settings", fil: "Pumunta sa Printer Settings", zh: "前往打印机设置", "zh-TW": "前往印表機設定", vi: "Đến Cài đặt máy in", th: "ไปที่การตั้งค่าเครื่องพิมพ์", id: "Buka Pengaturan Printer" },
